python3 - "$ROOT" <<'PY_EOF'
import json, os, subprocess, sys, time, shutil
from concurrent.futures import ThreadPoolExecutor

ROOT = sys.argv[1]
LANG = "cpp"
EXT  = "cpp"
MODE = "perfile"
OUT  = "/out/ld_cpp_00.txt"
out = open(OUT, "w")

def hms(x):
    if x is None or x < 0: return "--:--:--"
    x = int(x); return "%02d:%02d:%02d" % (x//3600, (x%3600)//60, x%60)

class Progress:
    def __init__(self, total, label, every=200):
        self.total=total; self.label=label; self.every=every
        self.done=0; self.t0=time.time(); self.last=0; self._emit()
    def tick(self, n=1):
        self.done += n
        if self.done-self.last >= self.every or self.done >= self.total:
            self.last=self.done; self._emit()
    def _emit(self):
        el=time.time()-self.t0
        eta=(el/self.done)*(self.total-self.done) if self.done else None
        print("[progress] %-16s [%d/%d] %5.1f%%  elapsed %s  ETA %s  mean %.1f ms"
              % (self.label, self.done, self.total,
                 100.0*self.done/self.total if self.total else 100.0,
                 hms(el), hms(eta),
                 1000.0*el/self.done if self.done else 0.0))
        sys.stdout.flush()
    def close(self):
        el=time.time()-self.t0
        print("[progress] %s DONE %d in %s (%.1f ms/probe)"
              % (self.label, self.done, hms(el),
                 1000.0*el/self.done if self.done else 0.0))
        sys.stdout.flush()


import re as _re
T = json.load(open(os.path.join(ROOT, "table.json")))
SPEC = json.load(open(os.path.join(ROOT, "shard.json")))
HS, OPS, TPL = T["holders"], T["ops"], T
LANG_ = T["language"]

def _rn(s, n):
    return _re.sub(r"\bv\b", n, s)

_DT = _re.compile(r"\b(?:record|class|interface|enum)\s+([A-Za-z_]\w*)")

def _side(decl, suffix):
    for n in sorted(set(_DT.findall(decl)), key=len, reverse=True):
        decl = _re.sub(r"\b%s\b" % _re.escape(n), n + suffix, decl)
    return decl

probes = []
for (i, j, x, y, k) in SPEC["rows"]:
    ha, hb = HS[i], HS[j]
    vca, da = ha["values"][x]
    vcb, db = hb["values"][y]
    da = _rn(da, "a"); db = _rn(db, "b")
    if LANG_ == "java":
        db = _side(db, "_b")
    pres = []
    for h, dtext in ((ha, da), (hb, db)):
        for line in (h.get("pre") or "").splitlines():
            line = line.strip()
            if not line:
                continue
            m = _re.findall(r"[A-Za-z_][A-Za-z_0-9]*", line)
            tok = m[-1] if m else ""
            if LANG_ in ("go", "rust") and tok and tok not in dtext:
                continue
            if line not in pres:
                pres.append(line)
    ident = "%d_%d_%d_%d_%d" % (i, j, x, y, k)
    src = (TPL["head"].replace("{PRE}", "\n".join(pres))
                      .replace("{ID}", ident)
           + TPL["decl"].replace("{D}", da))
    if SPEC.get("loadcheck"):
        # LOAD CHECK: the left declaration alone, no second operand and
        # no operation.  It answers the one question a value-matrix
        # split cannot answer by itself -- whether the value class moved
        # the OPERATION's verdict or simply failed to LOAD into the
        # holder (`short v = 9223372036854775807;` does not fit).  The
        # first is layer 3; the second is layer 2 leaking into it.
        src += TPL["tail"]
    else:
        src += (TPL["decl"].replace("{D}", db)
                + TPL["body"].replace("{A}", "a").replace("{B}", "b")
                             .replace("{OP}", OPS[k])
                + TPL["tail"])
    probes.append(dict(id="P" + ident, src=src))
print("probes assembled: %d (shard %d of %d)"
      % (len(probes), SPEC["shard"], SPEC["shards"]))
sys.stdout.flush()


SRC = os.path.join(ROOT, "src"); os.makedirs(SRC, exist_ok=True)
for p in probes:
    open(os.path.join(SRC, p["id"] + "." + EXT), "w").write(p["src"])
print("sources written"); sys.stdout.flush()

t_start = time.time()
verdicts = {}

def emit(pid, v, detail=""):
    out.write("%s|%s|%s\n" % (pid, v, detail.replace("\n", " ")[:200]))

if MODE == "perfile":
    CMD = {
      "go":    lambda f: ["go", "build", "-o", "/dev/null", f],
      # NOT -o /dev/null: rustc writes its metadata with a rename and
      # /dev/null answers EBUSY, which made every ACCEPTING probe look
      # like a refusal.  Measured and fixed 2026-08-18.
      "rust":  lambda f: ["rustc", "--emit=metadata",
                          "-o", f.replace(".rs", ".rmeta"), f],
      "cpp":   lambda f: ["g++", "-std=c++20", "-fsyntax-only", f],
      "swift": lambda f: ["/persist/swift/usr/bin/swiftc", "-typecheck", f],
    }[LANG]
    pg = Progress(len(probes), LANG, every=max(50, len(probes)//40))
    def work(p):
        f = os.path.join(SRC, p["id"] + "." + EXT)
        try:
            r = subprocess.run(CMD(f), capture_output=True, text=True,
                               cwd=ROOT, timeout=60)
            rc, err = r.returncode, (r.stderr or "")[:200]
        except Exception as e:
            rc, err = 99, "HARNESS:%s" % e
        return (p["id"], "ACCEPT" if rc == 0 else "REFUSE", err if rc else "")
    with ThreadPoolExecutor(max_workers=(os.cpu_count() or 4)) as ex:
        for pid, v, d in ex.map(work, probes):
            verdicts[pid] = v; emit(pid, v, d); pg.tick()
    pg.close()

elif MODE == "dart_dir":
    DART = "/persist/dart-sdk/bin/dart"
    CH = 500
    pg = Progress(len(probes), "dart", every=CH)
    for i in range(0, len(probes), CH):
        chunk = probes[i:i+CH]
        d = os.path.join(ROOT, "chunk"); shutil.rmtree(d, ignore_errors=True)
        os.makedirs(d)
        for p in chunk:
            open(os.path.join(d, p["id"] + ".dart"), "w").write(p["src"])
        r = subprocess.run([DART, "analyze", "."], capture_output=True,
                           text=True, cwd=d)
        bad = set()
        for line in (r.stdout or "").splitlines():
            for tok in line.split():
                if tok.startswith("P") and "." in tok:
                    bad.add(tok.split(".dart")[0])
        for p in chunk:
            v = "REFUSE" if p["id"] in bad else "ACCEPT"
            verdicts[p["id"]] = v; emit(p["id"], v, "")
        pg.tick(len(chunk))
    pg.close()

elif MODE == "roslyn":
    D = "/persist/dotnet"
    REF = "/persist/dotnet/packs/Microsoft.NETCore.App.Ref/10.0.11/ref/net10.0"
    CSC = D + "/sdk/10.0.400/Roslyn/bincore/csc.dll"
    drv = os.path.join(ROOT, "drv"); os.makedirs(drv, exist_ok=True)
    open(os.path.join(drv, "Drv.cs"), "w").write('''using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
public class Drv {
  public static int Main(string[] argv) {
    var refs = new List<MetadataReference>();
    foreach (var f in Directory.GetFiles(argv[0], "*.dll"))
      { try { refs.Add(MetadataReference.CreateFromFile(f)); } catch {} }
    var opts = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
    Check("class W { int f() { return 1; } }", refs, opts);
    var t0 = System.Diagnostics.Stopwatch.StartNew();
    int n = 0;
    foreach (var s in File.ReadAllLines(argv[1])) {
      if (s.Length == 0) continue;
      bool ok;
      try { ok = Check(File.ReadAllText(s), refs, opts); } catch { ok = false; }
      Console.WriteLine(Path.GetFileName(s) + "|" + (ok ? "ACCEPT" : "REFUSE"));
      n++;
    }
    Console.WriteLine("__TOTAL_MS__|" + t0.ElapsedMilliseconds + "|" + n);
    return 0;
  }
  static bool Check(string text, List<MetadataReference> refs,
                    CSharpCompilationOptions opts) {
    var tree = CSharpSyntaxTree.ParseText(text);
    var comp = CSharpCompilation.Create("c", new[] { tree }, refs, opts);
    return !comp.GetDiagnostics().Any(d => d.Severity == DiagnosticSeverity.Error);
  }
}
''')
    refs = ["-reference:" + os.path.join(REF, f)
            for f in os.listdir(REF) if f.endswith(".dll")]
    refs += ["-reference:" + D + "/sdk/10.0.400/Roslyn/bincore/" + n
             for n in ("Microsoft.CodeAnalysis.dll",
                       "Microsoft.CodeAnalysis.CSharp.dll")]
    r = subprocess.run([D + "/dotnet", "exec", CSC, "-nologo",
                        "-out:Drv.dll", "-target:exe"] + refs + ["Drv.cs"],
                       capture_output=True, text=True, cwd=drv)
    print("driver build rc=%d %s" % (r.returncode, (r.stdout or "")[:300]))
    for n in os.listdir(D + "/sdk/10.0.400/Roslyn/bincore"):
        if n.startswith("Microsoft.CodeAnalysis") or n.startswith("System."):
            try: shutil.copy(D + "/sdk/10.0.400/Roslyn/bincore/" + n, drv)
            except Exception: pass
    open(os.path.join(drv, "Drv.runtimeconfig.json"), "w").write(
      '{"runtimeOptions":{"tfm":"net10.0","framework":'
      '{"name":"Microsoft.NETCore.App","version":"10.0.11"}}}')
    lst = os.path.join(drv, "list.txt")
    open(lst, "w").write("\n".join(
        os.path.join(SRC, p["id"] + ".cs") for p in probes))
    pr = subprocess.Popen([D + "/dotnet", "Drv.dll", REF, lst],
                          stdout=subprocess.PIPE, text=True, cwd=drv)
    n = 0; t0 = time.time()
    for line in pr.stdout:
        line = line.strip()
        if "|" not in line: continue
        f, v = line.split("|", 1)
        if f == "__TOTAL_MS__": print("inner " + line); continue
        pid = f[:-3]
        verdicts[pid] = v; emit(pid, v, "")
        n += 1
        if n % 1000 == 0:
            el = time.time()-t0
            print("[progress] csharp [%d/%d] elapsed %s ETA %s mean %.2f ms"
                  % (n, len(probes), hms(el),
                     hms(el/n*(len(probes)-n)), 1000.0*el/n))
            sys.stdout.flush()
    pr.wait()

elif MODE == "kotlin_inproc":
    JAR = "/persist/kotlinc/lib/kotlin-compiler.jar"
    drv = os.path.join(ROOT, "drv"); os.makedirs(drv, exist_ok=True)
    open(os.path.join(drv, "KDrv.java"), "w").write('''import java.lang.reflect.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
public class KDrv {
  public static void main(String[] a) throws Exception {
    List<String> files = Files.readAllLines(Paths.get(a[0]));
    String outdir = a[1];
    Class<?> c = Class.forName("org.jetbrains.kotlin.cli.jvm.K2JVMCompiler");
    Object comp = c.getDeclaredConstructor().newInstance();
    Method exec = null;
    for (Method m : c.getMethods())
      if (m.getName().equals("exec") && m.getParameterCount() == 2
          && m.getParameterTypes()[0] == PrintStream.class) exec = m;
    if (exec == null) { System.out.println("__NO_EXEC__|x"); return; }
    ByteArrayOutputStream sink = new ByteArrayOutputStream();
    PrintStream ps = new PrintStream(sink);
    exec.invoke(comp, ps, new String[]{files.get(0), "-d", outdir + "/warm", "-nowarn"});
    long t0 = System.currentTimeMillis();
    int n = 0;
    for (String f : files) {
      if (f.isEmpty()) continue;
      sink.reset();
      Object rc;
      try { rc = exec.invoke(comp, ps,
              new String[]{f, "-d", outdir + "/o", "-nowarn"}); }
      catch (Throwable t) { rc = "HARNESS_ERROR"; }
      System.out.println(new File(f).getName() + "|" + rc);
      System.out.flush();
      n++;
    }
    System.out.println("__TOTAL_MS__|" + (System.currentTimeMillis()-t0) + "|" + n);
  }
}
''')
    r = subprocess.run(["javac", "-cp", JAR, "KDrv.java"],
                       capture_output=True, text=True, cwd=drv)
    print("driver build rc=%d %s" % (r.returncode, (r.stderr or "")[:300]))
    lst = os.path.join(drv, "list.txt")
    open(lst, "w").write("\n".join(
        os.path.join(SRC, p["id"] + ".kt") for p in probes))
    pr = subprocess.Popen(["java", "-cp", JAR + ":.", "KDrv", lst,
                           os.path.join(ROOT, "kout")],
                          stdout=subprocess.PIPE, text=True, cwd=drv)
    n = 0; t0 = time.time()
    for line in pr.stdout:
        line = line.strip()
        if "|" not in line: continue
        f, v = line.split("|", 1)
        if f == "__TOTAL_MS__": print("inner " + line); continue
        pid = f[:-3]
        verdicts[pid] = "ACCEPT" if v == "OK" else "REFUSE"
        emit(pid, verdicts[pid], v)
        n += 1
        if n % 200 == 0:
            el = time.time()-t0
            print("[progress] kotlin [%d/%d] elapsed %s ETA %s mean %.1f ms"
                  % (n, len(probes), hms(el),
                     hms(el/n*(len(probes)-n)), 1000.0*el/n))
            sys.stdout.flush()
    pr.wait()

elif MODE == "javac_inproc":
    drv = os.path.join(ROOT, "drv"); os.makedirs(drv, exist_ok=True)
    open(os.path.join(drv, "JDrv.java"), "w").write(r'''import javax.tools.*;
import com.sun.source.util.JavacTask;
import java.io.*;
import java.net.URI;
import java.nio.file.*;
import java.util.*;

// ROUTE A1 for java: the compiler's OWN checker, called in process
// through javax.tools, one JVM for the whole run.  JavacTask.analyze()
// runs parse + enter + attribute + flow and STOPS before code
// generation, so nothing is emitted; the verdict is javac's own
// diagnostic list, not a reading of it.
public class JDrv {
  static class Src extends SimpleJavaFileObject {
    final String code;
    Src(String name, String code) {
      super(URI.create("string:///" + name + ".java"), Kind.SOURCE);
      this.code = code;
    }
    public CharSequence getCharContent(boolean ignore) { return code; }
  }
  static class MemOut extends SimpleJavaFileObject {
    MemOut(String n) { super(URI.create("mem:///" + n + ".class"), Kind.CLASS); }
    public OutputStream openOutputStream() { return new ByteArrayOutputStream(); }
  }
  public static void main(String[] a) throws Exception {
    List<String> files = Files.readAllLines(Paths.get(a[0]));
    JavaCompiler c = ToolProvider.getSystemJavaCompiler();
    if (c == null) { System.out.println("__NOTE__|NO_SYSTEM_COMPILER"); return; }
    StandardJavaFileManager sfm = c.getStandardFileManager(null, null, null);
    JavaFileManager fm = new ForwardingJavaFileManager<StandardJavaFileManager>(sfm) {
      public JavaFileObject getJavaFileForOutput(Location l, String n,
          JavaFileObject.Kind k, FileObject s) { return new MemOut(n); }
    };
    List<String> opts = Arrays.asList("-proc:none", "-nowarn");
    check(c, fm, opts, "W", "class W { int f() { return 1; } }");
    long t0 = System.currentTimeMillis();
    int n = 0;
    for (String f : files) {
      if (f.isEmpty()) continue;
      String name = new File(f).getName();
      String base = name.substring(0, name.length() - 5);
      boolean ok;
      try {
        ok = check(c, fm, opts, base,
                   new String(Files.readAllBytes(Paths.get(f))));
      } catch (Throwable t) { ok = false; }
      System.out.println(base + "|" + (ok ? "ACCEPT" : "REFUSE"));
      n++;
      if ((n % 2000) == 0) System.out.flush();
    }
    System.out.println("__TOTAL_MS__|" + (System.currentTimeMillis()-t0) + "|" + n);
    System.out.flush();
  }
  static boolean check(JavaCompiler c, JavaFileManager fm, List<String> opts,
                       String base, String code) throws Exception {
    DiagnosticCollector<JavaFileObject> dc = new DiagnosticCollector<>();
    JavacTask t = (JavacTask) c.getTask(new PrintWriter(new StringWriter()),
        fm, dc, opts, null, Arrays.asList(new Src(base, code)));
    try { t.analyze(); } catch (Throwable e) { /* diagnostics decide */ }
    for (Diagnostic<? extends JavaFileObject> d : dc.getDiagnostics())
      if (d.getKind() == Diagnostic.Kind.ERROR) return false;
    return true;
  }
}
''')
